nasal.open:
            # Cargo Hauling option
            var p = getprop("sim/gui/dialogs/aicargo-dialog/connection");
            setprop("/sim/model/bo105/cargo_connection_flag_0", 0);
            setprop("/sim/model/bo105/cargo_connection_flag_1", 0);
            setprop("/sim/model/bo105/cargo_connection_flag_" ~ p, 1);

            # Long Line option
            p = getprop("sim/gui/dialogs/aicargo-dialog/longline");
            setprop("/sim/model/bo105/longline_flag_0",0);
						setprop("/sim/model/bo105/longline_flag_1",0);
            setprop("/sim/model/bo105/longline_flag_" ~ p, 1);

            # Hitch/Winch option
            p = getprop("sim/gui/dialogs/aicargo-dialog/connector");
            setprop("/sim/model/bo105/connector_flag_0",0);
						setprop("/sim/model/bo105/connector_flag_1",0);
            setprop("/sim/model/bo105/connector_flag_" ~ p, 1);

binding.script:
            var p = "sim/gui/dialogs/aicargo-dialog/connection";
            setprop(p, var i = 0);
            gui.popupTip("Cargo connection " ~ (i ? "Long Line" : "Hard Docked"));
            setprop("sim/model/bo105/cargo_connection_flag_0",1);
						setprop("sim/model/bo105/cargo_connection_flag_1",0);

            var p = "sim/gui/dialogs/aicargo-dialog/connection";
            setprop(p, var i = 1);
            gui.popupTip("Cargo connection " ~ (i ? "Long Line" : "Hard Docked"));
            setprop("sim/model/bo105/cargo_connection_flag_0",0);
						setprop("sim/model/bo105/cargo_connection_flag_1",1);
            setprop("sim/model/firetank/enabled", 0);

            var p = "sim/gui/dialogs/aicargo-dialog/longline";
            setprop(p, var i = 0);
            gui.popupTip("Line type " ~ (i ? "Cable" : "Rope"));
            setprop("sim/model/bo105/longline_flag_0",1);
						setprop("sim/model/bo105/longline_flag_1",0);

            var p = "sim/gui/dialogs/aicargo-dialog/longline";
            setprop(p, var i = 1);
            gui.popupTip("Line type " ~ (i ? "Cable" : "Rope"));
            setprop("sim/model/bo105/longline_flag_0",0);
						setprop("sim/model/bo105/longline_flag_1",1);

            var p = "sim/gui/dialogs/aicargo-dialog/connector";
            setprop(p, var i = 0);
            gui.popupTip("Connector type " ~ (i ? "Winch" : "Hitch"));
            setprop("sim/model/bo105/connector_flag_0",1);
						setprop("sim/model/bo105/connector_flag_1",0);

group.radio:
				left
				WinchHitch
				sim/model/bo105/connector_flag_1
				true



						  /sim/freeze/replay-state

            /sim/gui/dialogs/aicargo-dialog/connection



          nasal

            var p = "sim/gui/dialogs/aicargo-dialog/connector";
            setprop(p, var i = 1);
            gui.popupTip("Connector type " ~ (i ? "Winch" : "Hitch"));
            setprop("sim/model/bo105/connector_flag_0",0);
						setprop("sim/model/bo105/connector_flag_1",1);
